"""Parts 12-13: Task buddy's reward line matches what a session earns; "Break it down again" keeps the person's own
steps and sends them with the request; Inner Atlas description is whole at three phone widths.
Run with the app served on :8811:  python3 tests/tools_parts12_13.py"""
import sys, os, json
sys.path.insert(0, os.path.dirname(__file__))
from harness import start
OUT=os.path.join(os.path.dirname(__file__),"out"); os.makedirs(OUT,exist_ok=True)
res=[]
def ok(n,c,info=""): res.append(bool(c)); print(("PASS " if c else "FAIL ")+n+(("  ["+str(info)+"]") if info and not c else ""))
p,b,ctx,pg,errs=start(seed={"ek-agreed":"2026-11-01"},wait=2600)
pg.evaluate("()=>document.querySelector('#focusCard').click()"); pg.wait_for_timeout(800)
line=pg.inner_text("#fReward"); ok("reward line: no claim that every session lights a lantern", "Each session" not in line and "Two minutes or more lights a lantern" in line and line.startswith("Stop whenever you need."), line)
pg.evaluate("()=>{profile.lanterns=16;fRender();}"); full=pg.inner_text("#fReward")
ok("reward line once the path is full: says so, still counts", "fully lit" in full and "Task buddy achievements" in full, full)
pg.evaluate("()=>{profile.lanterns=0;fRender();}")
pg.evaluate("()=>{document.querySelector('#fTask').value='Write the funding application'}")
# a companion reply that ignores the person's steps, and records what it was asked
pg.evaluate("""()=>{window.__asked=[];sample={json:async(q)=>{window.__asked.push(q);return {steps:['Open the application form','Write the project summary','Check the budget figures','Submit it']};}};}""")
pg.evaluate("async()=>{ask=async()=>'Ring Priya about the letter of support';document.querySelector('#fBreak').click();await new Promise(r=>setTimeout(r,300));document.querySelector('#fAdd').click();await new Promise(r=>setTimeout(r,300));}")
steps=lambda: pg.evaluate("()=>fSteps.map(s=>(s.mine?'*':'')+(s.done?'[x]':'')+s.t)")
s1=steps(); ok("Add your own step marks it as the person's", any(x.startswith("*") and "Priya" in x for x in s1), s1)
pg.evaluate("()=>{fSteps[0].done=true;}")
pg.evaluate("async()=>{document.querySelector('#fBreak').click();await new Promise(r=>setTimeout(r,400));}")
asked=pg.evaluate("()=>window.__asked[window.__asked.length-1]"); s2=steps()
ok("the request carries their current steps and their own step", "Ring Priya about the letter of support" in asked and "They wrote these steps themselves" in asked, asked[-300:])
ok("their step survives a reply that leaves it out", any("Priya" in x and x.startswith("*") for x in s2), s2)
ok("a ticked step stays ticked", any(x.startswith("[x]") or x.startswith("*[x]") for x in s2) and "[x]Open the application form" in s2, s2)
pg.evaluate("async()=>{for(let i=0;i<3;i++){document.querySelector('#fBreak').click();await new Promise(r=>setTimeout(r,350));}}")
s3=steps(); ok("repeated Break it down again keeps it, once", sum("Priya" in x for x in s3)==1, s3)
pg.evaluate("()=>{sample={json:async(q)=>{window.__asked.push(q);return {steps:['Ring Priya about a support letter','Open the form','Write one paragraph']};}};}")
pg.evaluate("async()=>{document.querySelector('#fBreak').click();await new Promise(r=>setTimeout(r,400));}")
s4=steps(); ok("a tidied version of their step counts as theirs (no duplicate)", sum("Priya" in x for x in s4)==1 and any(x.startswith("*") and "Priya" in x for x in s4), s4)
pg.evaluate("()=>{sample=null;}"); before=steps()
pg.evaluate("async()=>{document.querySelector('#fBreak').click();await new Promise(r=>setTimeout(r,400));}")
ok("when the companion can't be reached, their steps are kept as they were", steps()==before, [before,steps()])
pg.evaluate("async()=>{ask=async()=>'   ';document.querySelector('#fAdd').click();await new Promise(r=>setTimeout(r,300));}")
ok("an empty step isn't added", steps()==before)
# editing: any step can be reworded (it becomes theirs) or removed by saving it empty
pg.evaluate("()=>{sample={json:async(q)=>{window.__asked.push(q);return {steps:['Open the form','Write one paragraph','Submit it']};}};}")
n0=len(steps()); edit_i=pg.evaluate("()=>fSteps.findIndex(s=>!s.mine)")
pg.evaluate("async i=>{ask=async(o)=>{window.__askv=o.value;return 'Draft the budget table first';};document.querySelectorAll('#fSteps .fedit')[i].click();await new Promise(r=>setTimeout(r,250));}",edit_i)
s5=steps(); ok("pencil opens the step's own words for editing", pg.evaluate("()=>window.__askv") and any(x.startswith("*") and "Draft the budget table first" in x for x in s5), [pg.evaluate("()=>window.__askv"),s5])
pg.evaluate("async()=>{document.querySelector('#fBreak').click();await new Promise(r=>setTimeout(r,400));}")
ok("an edited step survives Break it down again", any("Draft the budget table first" in x for x in steps()), steps())
k=pg.evaluate("()=>fSteps.findIndex(s=>/budget table/.test(s.t))")
pg.evaluate("async i=>{ask=async()=>'';document.querySelectorAll('#fSteps .fedit')[i].click();await new Promise(r=>setTimeout(r,250));}",k)
ok("saving a step empty removes it", not any("budget table" in x for x in steps()), steps())
pg.evaluate("async()=>{ask=async()=>null;document.querySelectorAll('#fSteps .fedit')[0].click();await new Promise(r=>setTimeout(r,250));}")
pg.evaluate("()=>document.querySelector('#fSteps').scrollIntoView({block:'center'})"); pg.wait_for_timeout(400)
eb=pg.evaluate("()=>{const b=document.querySelector('#fSteps .fedit').getBoundingClientRect();return [b.width,b.height]}")
ok("the pencil is a 44px touch target", eb[0]>=44 and eb[1]>=44, eb)
pg.screenshot(path=os.path.join(OUT,"42_taskbuddy_edit.png"))
pg.evaluate("()=>document.querySelector('#fStart')&&document.querySelector('#fReward').scrollIntoView({block:'center'})"); pg.wait_for_timeout(400)
pg.screenshot(path=os.path.join(OUT,"40_taskbuddy_steps.png"))
ok("Parts 12: no script errors", not [e for e in errs if "net::" not in e], [e for e in errs if "net::" not in e][:3])
b.close(); p.stop()
for (w,h) in [(360,740),(412,860),(430,932)]:
    p,b,ctx,pg,errs=start(seed={"ek-agreed":"2026-11-01"},w=w,h=h,dpr=2,wait=2400)
    pg.evaluate("()=>document.querySelector('#atlasCard').scrollIntoView({block:'center'})"); pg.wait_for_timeout(500)
    r=pg.evaluate("""()=>{const c=document.querySelector('#atlasCard'),a=c.getBoundingClientRect(),out=[];for(const s of c.querySelectorAll('small')){const q=s.getBoundingClientRect();out.push({t:s.textContent.slice(0,20),clip:s.scrollHeight>s.clientHeight+1||q.bottom>a.bottom+.5||q.right>a.right+.5});}
      const box=c.querySelector('small.atldesc').parentElement.getBoundingClientRect();return {txt:c.querySelector('small.atldesc').textContent,out,boxIn:box.bottom<=a.bottom+.5}}""")
    ok(f"{w}: Inner Atlas description is the new wording, whole and unclipped", r["txt"].startswith("Explore how body, mind & emotions connect.") and not any(o["clip"] for o in r["out"]) and r["boxIn"], r)
    bb=pg.evaluate("()=>{const r=document.querySelector('#atlasCard').getBoundingClientRect();return [r.top,r.bottom]}")
    pg.screenshot(path=os.path.join(OUT,f"41_atlas_{w}.png"),clip={"x":0,"y":max(0,bb[0]-6),"width":w,"height":bb[1]-bb[0]+12})
    b.close(); p.stop()
print("\n%d passed, %d failed"%(sum(res),len(res)-sum(res)))
